# Day 36 Part 3: Asymmetric Cryptographic Branch Execution Profiler
import struct

class AsymmetricBranchProfiler:
    """Profiles execution patterns of naive Square-and-Multiply vs Double-and-Add."""
    def __init__(self):
        # Microsecond timing and power profiles for sub-operations
        self.op_signatures = {
            'SQUARE':   {'duration_us': 12.0, 'mean_ma': 18.5, 'cycles': 1200},
            'MULTIPLY': {'duration_us': 22.0, 'mean_ma': 34.2, 'cycles': 2200},
            'DOUBLE':   {'duration_us': 15.0, 'mean_ma': 21.0, 'cycles': 1500},
            'ADD':      {'duration_us': 26.0, 'mean_ma': 38.0, 'cycles': 2600}
        }

    def simulate_naive_rsa_modular_exp(self, base: int, exponent: int, modulus: int) -> tuple[int, list]:
        """Executes naive square-and-multiply, logging the operational execution trace."""
        exp_bits = bin(exponent)[2:]  # Convert to binary string
        accumulator = 1
        trace_log = []

        # Start from MSB (skip leading 1 in standard execution or include it)
        for bit_idx, bit_char in enumerate(exp_bits):
            # Square step always occurs
            accumulator = (accumulator * accumulator) % modulus
            trace_log.append({
                'bit_index': bit_idx,
                'bit_val': int(bit_char),
                'operation': 'SQUARE',
                'profile': self.op_signatures['SQUARE']
            })
            # Conditional multiply if bit is 1
            if bit_char == '1':
                accumulator = (accumulator * base) % modulus
                trace_log.append({
                    'bit_index': bit_idx,
                    'bit_val': int(bit_char),
                    'operation': 'MULTIPLY',
                    'profile': self.op_signatures['MULTIPLY']
                })

        return accumulator, trace_log

if __name__ == '__main__':
    profiler = AsymmetricBranchProfiler()
    secret_exp = 0b10110  # 22 in decimal
    res, trace = profiler.simulate_naive_rsa_modular_exp(base=7, exponent=secret_exp, modulus=101)
    print(f"=== RSA Square-and-Multiply Execution Log (Secret Exp: {bin(secret_exp)}) ===")
    print(f"Result (7^{secret_exp} mod 101): {res}")
    for step in trace:
        print(f"Bit [{step['bit_index']}]: Val {step['bit_val']} -> Op: {step['operation']:8s} | Duration: {step['profile']['duration_us']:4.1f} us | Current: {step['profile']['mean_ma']:4.1f} mA")

# Day 37 Part 2: Hamming Weight vs Hamming Distance Physical Leakage Model
import struct

class PowerLeakageModels:
    """Calculates theoretical power consumption based on HW and HD transition models."""
    def __init__(self, capacitance_per_bit_pf: float = 1.2, vdd_volts: float = 3.3):
        self.c_bit = capacitance_per_bit_pf * 1e-12
        self.vdd = vdd_volts
        # Energy per bit transition = 0.5 * C * Vdd^2
        self.energy_per_transition_pj = (0.5 * self.c_bit * (self.vdd ** 2)) * 1e12

    @staticmethod
    def hamming_weight(value: int) -> int:
        """Calculates number of set bits (popcount)."""
        return bin(value).count('1')

    @classmethod
    def hamming_distance(cls, val_prev: int, val_next: int) -> int:
        """Calculates number of toggling bits between two consecutive states."""
        return cls.hamming_weight(val_prev ^ val_next)

    def calculate_transition_energy(self, prev_state: int, next_state: int) -> dict:
        hw_prev = self.hamming_weight(prev_state)
        hw_next = self.hamming_weight(next_state)
        hd = self.hamming_distance(prev_state, next_state)
        total_energy_pj = hd * self.energy_per_transition_pj

        return {
            'prev_hex': hex(prev_state),
            'next_hex': hex(next_state),
            'hw_prev': hw_prev,
            'hw_next': hw_next,
            'hamming_distance': hd,
            'switching_energy_pj': round(total_energy_pj, 3)
        }

if __name__ == '__main__':
    models = PowerLeakageModels()
    print("=== Hamming Weight vs Hamming Distance Physical Energy Model ===")
    test_transitions = [
        (0x00, 0xFF),  # 0 -> 8 bits set (8 toggles)
        (0xFF, 0xFF),  # 8 -> 8 bits set (0 toggles, static)
        (0xAA, 0x55),  # 4 -> 4 bits set (8 toggles: 10101010 -> 01010101)
        (0x0F, 0x07),  # 4 -> 3 bits set (1 toggle)
        (0x00, 0x01)   # 0 -> 1 bit set  (1 toggle)
    ]
    for prev_val, next_val in test_transitions:
        res = models.calculate_transition_energy(prev_val, next_val)
        print(f"[{res['prev_hex']:4s} -> {res['next_hex']:4s}] HW_prev: {res['hw_prev']} | HW_next: {res['hw_next']} | HD: {res['hamming_distance']} | Energy: {res['switching_energy_pj']:6.3f} pJ")
